 "content": "from collections import Counter

def transform(grid):
    counts = Counter(v for row in grid for v in row if v not in (0, 7, 9, 6))
    # Select the most prevalent colored shape, ignoring background/noise colors.
    color = max(counts, key=counts.get)
    return [[color] * 3 for _ in range(3)]
